     private function normalizeWeekdayArray(array $days): array
     {
         $normalized = array_values(array_unique(array_map('intval', $days)));
         $normalized = array_values(array_filter($normalized, fn ($d) => $d >= 1 && $d <= 7));
         sort($normalized);
         return $normalized;
     }
