+    private function normalizeDayTimeSlots(array $slots): array
+    {
+        $result = [];
+        foreach ($slots as $slot) {
+            $day = (int) ($slot['day'] ?? 0);
+            $time = isset($slot['start_time']) ? trim((string) $slot['start_time']) : '';
+            if ($day < 1 || $day > 7 || $time === '') {
+                continue;
+            }
+            $result[$day] = $this->normalizeTime(substr($time, 0, 5));
+        }
+        ksort($result);
+        return $result;
+    }
