export const SUBJECTS = [
    { value: 'Chinese', label: '國文 (Chinese)' },
    { value: 'English', label: '英文 (English)' },
    { value: 'Math', label: '數學 (Math)' },
    { value: 'Science', label: '自然 (Science)' },
